}

public class Main {
    public static void main(String[] args) {
        Calc c = new Calc();
        c.base = 10;
        Calc d = new Calc();
        d.base = 3;
        System.out.println(c.add(d.base) + d.add(c.base));
    }
}

class Secure {
    private int code = 7;

    private int twist() {
        return code * 3;
    }

    public int unlock() {
        return twist() + code;
    }
}

public class Main {
    public static void main(String[] args) {
        Secure s = new Secure();
        System.out.println(s.unlock());
    }
}

