class Tally {
    static int shared = 0;
    int own = 0;

    void bump() {
        shared++;
        own++;
    }
}

public class Main {
    public static void main(String[] args) {
        Tally p = new Tally();
        Tally q = new Tally();
        p.bump();
        p.bump();
        q.bump();
        System.out.println(p.own + " " + q.own + " " + Tally.shared);
    }
}
